/* BTV — stile per TV 1920x1080 (scala con la larghezza). Evita CSS Grid / variabili per le TV più vecchie. */
html { font-size: 0.8333vw; } /* 16px a 1920px */
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #0b0d12; color: #e8eaf0;
  font-family: "Samsung One", "LG Smart UI", Roboto, "Segoe UI", Helvetica, Arial, sans-serif; }
button, input { font: inherit; color: inherit; }
.hidden { display: none !important; }

#app { position: relative; width: 100vw; height: 100vh; }
.screen { position: absolute; top: 0; left: 0; right: 0; bottom: 0; display: none; }
.screen.active { display: flex; }

/* ---------- elementi con focus ---------- */
.focusable { outline: none; transition: transform .12s ease, background-color .12s ease, border-color .12s ease; }
.btn { background: #1c2130; border: .15rem solid #2a3145; border-radius: .7rem; padding: .8rem 1.5rem;
  font-size: 1.25rem; cursor: pointer; white-space: nowrap; }
.btn.primary { background: #2f6bff; border-color: #2f6bff; color: #fff; }
.btn.danger { background: #3a1c22; border-color: #5a2630; }
.btn.focused { background: #fff; color: #0b0d12; border-color: #fff; transform: scale(1.06); }

/* ---------- sidebar ---------- */
#sidebar { width: 22rem; flex: none; background: #10131b; padding: 2.5rem 1.2rem 2rem 2.5rem;
  display: flex; flex-direction: column; border-right: .1rem solid #1a1f2c; }
.brand { font-size: 2rem; font-weight: 800; letter-spacing: .05rem; margin-bottom: 2rem; display: flex; align-items: center; }
.brand-mark { display: inline-block; width: 2.6rem; height: 2.6rem; line-height: 2.6rem; text-align: center;
  border-radius: .7rem; background: #e8466e; background-image: linear-gradient(135deg, #ff6a3d, #c4209c);
  font-size: 1.6rem; font-weight: 900; margin-right: .8rem; color: #fff; }
#groups { flex: 1; overflow-y: auto; overflow-x: hidden; padding: .3rem .4rem .3rem 0; }
#groups::-webkit-scrollbar, #grid::-webkit-scrollbar { width: 0; }
.group { display: flex; justify-content: space-between; align-items: center; padding: .8rem 1rem;
  border-radius: .7rem; font-size: 1.3rem; color: #aab1c3; cursor: pointer; margin-bottom: .2rem; }
.group .gname { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-right: .8rem; }
.group .gcount { font-size: 1rem; color: #6c7488; flex: none; }
.group.active { color: #fff; background: #1c2130; }
.group.active .gcount { color: #9fb6ff; }
.group.focused { background: #fff; color: #0b0d12; transform: scale(1.03); }
.group.focused .gcount { color: #444; }

/* ---------- area principale ---------- */
#main { flex: 1; display: flex; flex-direction: column; padding: 2.5rem 3rem 1.2rem 2.5rem; min-width: 0; }
#topbar { display: flex; align-items: center; margin-bottom: 1rem; }
#search { width: 32rem; background: #161a25; border: .15rem solid #2a3145; border-radius: .8rem; padding: .9rem 1.2rem;
  font-size: 1.3rem; }
#search.focused { border-color: #fff; background: #1f2433; }
#search:focus { border-color: #2f6bff; }
#playlist-name { flex: 1; text-align: right; margin-right: 1.5rem; color: #7d859a; font-size: 1.2rem;
  overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
#btn-multi { margin-right: .8rem; }
#status { font-size: 1.15rem; color: #7d859a; min-height: 1.6rem; margin: .3rem 0 .7rem; }
#status.error { color: #ff8b8b; }
#hint { font-size: 1rem; color: #4f566a; padding-top: .7rem; }

#grid { flex: 1; overflow-y: auto; overflow-x: hidden; display: flex; flex-wrap: wrap; align-content: flex-start;
  padding: .8rem .4rem 3rem .4rem; margin: 0 -.6rem; }
.card { position: relative; width: 13.2rem; height: 12.4rem; margin: .6rem; border-radius: 1rem; background: #161a25;
  border: .2rem solid transparent; overflow: hidden; cursor: pointer; display: flex; flex-direction: column; }
.card .clogo { flex: 1; display: flex; align-items: center; justify-content: center; padding: 1rem 1.2rem .4rem;
  background: #1c2130; min-height: 0; }
.clogo img { max-width: 100%; max-height: 100%; object-fit: contain; }
.initials { font-size: 2.6rem; font-weight: 800; color: #5c6684; }
.card .cname { font-size: 1.1rem; padding: .55rem .8rem .2rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card .cnum { position: absolute; top: .45rem; left: .6rem; font-size: .85rem; color: #8b93a8; background: rgba(11, 13, 18, .75);
  padding: .05rem .45rem; border-radius: .4rem; }
.card .cnow { font-size: .9rem; color: #8b93a8; padding: 0 .8rem .75rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  min-height: 1.85rem; }
.card .cbar { position: absolute; left: 0; right: 0; bottom: 0; height: .3rem; background: rgba(255, 255, 255, .08); }
.card .cbar i, .osd-bar i, .gi-bar i { display: block; height: 100%; background: #2f6bff; }
.card .cstar { position: absolute; top: .5rem; right: .7rem; color: #ffc93c; font-size: 1.4rem; display: none;
  text-shadow: 0 0 .4rem #000; }
.card.fav .cstar { display: block; }
.card.focused { border-color: #fff; transform: scale(1.08); background: #222839; z-index: 2;
  box-shadow: 0 .8rem 2.5rem rgba(0, 0, 0, .6); }

/* ---------- lettore ---------- */
#player { background: #000; }
#video { width: 100%; height: 100%; background: #000; object-fit: contain; }
#spinner { position: absolute; top: 50%; left: 50%; margin: -3rem 0 0 -3rem; display: none; }
#spinner.on { display: block; }
.ring { width: 6rem; height: 6rem; border-radius: 50%; border: .5rem solid rgba(255, 255, 255, .15);
  border-top-color: #fff; -webkit-animation: spin 1s linear infinite; animation: spin 1s linear infinite; }
@-webkit-keyframes spin { to { -webkit-transform: rotate(360deg); } }
@keyframes spin { to { transform: rotate(360deg); } }

#player-error { position: absolute; top: 50%; left: 50%; width: 60rem; margin-left: -30rem; transform: translateY(-50%);
  text-align: center; background: rgba(16, 19, 27, .92); border-radius: 1.2rem; padding: 2.5rem; }
.perr-title { font-size: 2.2rem; font-weight: 700; margin-bottom: .8rem; }
.perr-msg { font-size: 1.3rem; color: #aab1c3; margin-bottom: 1.2rem; }
.perr-help { font-size: 1.1rem; color: #6c7488; }

#live-badge { position: absolute; top: 2.5rem; left: 3rem; font-size: 1.3rem; font-weight: 700; color: #fff;
  background: rgba(229, 72, 77, .92); border: 0; border-radius: 3rem; padding: .7rem 1.6rem; cursor: pointer; z-index: 5;
  box-shadow: 0 .4rem 1.5rem rgba(0, 0, 0, .5); }
#live-badge.focused { outline: .2rem solid #fff; }
#numjump { position: absolute; top: 3rem; right: 4rem; font-size: 4rem; font-weight: 800; background: rgba(0, 0, 0, .7);
  padding: .5rem 1.8rem; border-radius: 1rem; letter-spacing: .3rem; }

#osd { position: absolute; left: 0; right: 0; bottom: 0; padding: 7rem 4rem 2rem;
  background: linear-gradient(to top, rgba(0, 0, 0, .94), rgba(0, 0, 0, .7) 60%, transparent);
  display: flex; flex-direction: column; }
.osd-info { display: flex; align-items: center; min-width: 0; }
.osd-text { flex: 1; min-width: 0; }
.osd-epg { width: 50rem; flex: none; margin-left: 2rem; }
.osd-now { font-size: 1.35rem; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.osd-bar { height: .35rem; background: rgba(255, 255, 255, .15); border-radius: .2rem; margin: .5rem 0; overflow: hidden; }
.osd-next { font-size: 1.1rem; color: #aab1c3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.osd-shift { font-size: 1.15rem; color: #ffc93c; margin: 1.2rem 0 .8rem; }
.osd-shift.live { color: #ff5a5a; }
.osd-help { font-size: .95rem; color: #6c7488; margin-top: .8rem; }
.osd-sep { flex: 1; }
.osd-logo { width: 9rem; height: 6rem; border-radius: .8rem; background: rgba(255, 255, 255, .08); display: flex;
  align-items: center; justify-content: center; padding: .6rem; margin-right: 1.6rem; flex: none; }
.osd-logo img { max-width: 100%; max-height: 100%; object-fit: contain; }
.osd-num { font-size: 1.2rem; color: #9fb6ff; font-weight: 700; }
.osd-name { font-size: 2.4rem; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 70rem; }
.osd-group { font-size: 1.15rem; color: #aab1c3; margin-top: .3rem; }
.osd-buttons { display: flex; align-items: center; flex-wrap: wrap; }
.osd-buttons .btn { margin: 0 .55rem .5rem 0; font-size: 1.1rem; padding: .65rem 1rem; }

/* Canali che non hanno funzionato di recente: attenuati e con l'avviso */
.card.dead { opacity: .45; }
.card.dead .cname::before { content: ''; display: inline-block; width: .55rem; height: .55rem; border-radius: 50%; background: #ffb02e; margin-right: .5rem; vertical-align: middle; }
.pk-row.dead { opacity: .5; }

/* ---------- multivisione ---------- */
#multi { background: #000; flex-direction: column; }
#multi-bar { display: flex; align-items: center; padding: .8rem 1.2rem 0; }
.mb-title { font-size: 1.3rem; font-weight: 700; margin-right: 1.5rem; color: #aab1c3; }
#multi-bar .btn { margin-right: .7rem; font-size: 1.05rem; padding: .5rem 1.1rem; }
#multi-grid { flex: 1; min-height: 0; display: flex; flex-wrap: wrap; align-content: center; justify-content: center; padding: .6rem; }
.tile { position: relative; background: #0b0d12; border: .25rem solid #1a1f2c; margin: .3rem; overflow: hidden; cursor: pointer; border-radius: .4rem; }
#multi-grid.n4 .tile { width: calc(50% - .6rem); height: calc(50% - .6rem); }
#multi-grid.n2 .tile { width: calc(50% - .6rem); height: calc((50vw - 1.8rem) * 9 / 16); }
.tile video { width: 100%; height: 100%; object-fit: contain; background: #000; display: block; }
.tile.focused { border-color: #fff; }
.tile.empty video, .tile.empty .tile-label { display: none; }
.tile-empty { display: none; position: absolute; top: 0; left: 0; right: 0; bottom: 0; align-items: center; justify-content: center;
  flex-direction: column; font-size: 1.6rem; color: #6c7488; }
.tile-empty small { font-size: 1rem; margin-top: .4rem; }
.tile.empty .tile-empty { display: flex; }
.tile.focused .tile-empty { color: #fff; }
.tile-spin { display: none; position: absolute; top: 50%; left: 50%; margin: -3rem 0 0 -3rem; }
.tile.loading .tile-spin { display: block; }
.tile-err { position: absolute; left: 10%; right: 10%; top: 40%; text-align: center; font-size: 1.2rem; color: #ffb4b4;
  background: rgba(16, 19, 27, .9); padding: 1rem; border-radius: .8rem; }
/* Nome canale nascosto: compare per qualche secondo quando ti muovi, premi OK o cambi canale. */
.tile-label { position: absolute; left: 0; right: 0; top: 0; padding: .7rem 1rem 2rem;
  background: linear-gradient(to bottom, rgba(0, 0, 0, .8), transparent); font-size: 1.15rem;
  opacity: 0; transition: opacity .25s ease; pointer-events: none; }
.tile.show-label .tile-label { opacity: 1; }
.tl-num { color: #9fb6ff; font-weight: 700; margin-right: .6rem; }
.tl-name { font-weight: 700; }
.tile-audio { display: none; position: absolute; top: .6rem; right: .7rem; font-size: 1.3rem; background: rgba(0, 0, 0, .55);
  border-radius: 50%; width: 2.4rem; height: 2.4rem; line-height: 2.4rem; text-align: center; }
.tile.audio .tile-audio { display: block; }
.tile-live { position: absolute; right: .7rem; bottom: .7rem; font-size: 1rem; font-weight: 700; color: #fff; background: #e5484d;
  border: 0; border-radius: 2rem; padding: .35rem .9rem; cursor: pointer; }
.tile.menu-open .tile-live { display: none; }
.tl-now { font-size: .95rem; color: #aab1c3; margin-top: .2rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tile-menu { position: absolute; left: 0; right: 0; bottom: 0; padding: 1rem; display: flex; justify-content: center;
  background: linear-gradient(to top, rgba(0, 0, 0, .9), transparent); }
.tile-menu .btn { margin: 0 .4rem; font-size: 1.1rem; padding: .6rem 1rem; }
#multi-hint { font-size: 1rem; color: #6c7488; text-align: center; padding: 0 0 .8rem; }

#picker { position: absolute; top: 0; right: 0; bottom: 0; width: 40rem; background: rgba(13, 16, 23, .97);
  border-left: .1rem solid #222839; display: flex; flex-direction: column; z-index: 25; box-shadow: -1rem 0 3rem rgba(0, 0, 0, .5); }
#picker-list { flex: 1; overflow-y: auto; padding: 0 1.2rem 1.2rem; }
#picker-list::-webkit-scrollbar { width: 0; }
.pk-row { display: flex; align-items: baseline; padding: .65rem .8rem; border-radius: .6rem; cursor: pointer; }
.pk-num { width: 3.6rem; flex: none; color: #9fb6ff; font-weight: 600; font-size: 1.05rem; }
.pk-name { font-size: 1.2rem; flex: none; max-width: 17rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-right: 1rem; }
.pk-now { flex: 1; min-width: 0; font-size: .95rem; color: #7d859a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pk-row.sel { background: #fff; color: #0b0d12; }
.pk-row.sel .pk-now { color: #444; }

/* ---------- pannello guida ---------- */
#guide { position: absolute; top: 0; right: 0; bottom: 0; width: 46rem; background: rgba(13, 16, 23, .97);
  border-left: .1rem solid #222839; display: flex; flex-direction: column; z-index: 20; box-shadow: -1rem 0 3rem rgba(0, 0, 0, .5); }
.guide-head { display: flex; align-items: center; padding: 2.2rem 2rem 1.2rem; }
.guide-logo { width: 7rem; height: 4.6rem; border-radius: .7rem; background: #1c2130; display: flex; align-items: center;
  justify-content: center; padding: .5rem; margin-right: 1.2rem; flex: none; }
.guide-logo img { max-width: 100%; max-height: 100%; object-fit: contain; }
.guide-titles { flex: 1; min-width: 0; }
.guide-ch { font-size: 1.8rem; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.guide-sub { font-size: .95rem; color: #6c7488; margin-top: .3rem; }
#guide-list { flex: 1; overflow-y: auto; padding: 0 1.2rem; }
#guide-list::-webkit-scrollbar { width: 0; }
.guide-day { font-size: 1rem; color: #7d859a; text-transform: uppercase; letter-spacing: .1rem; padding: 1rem .8rem .4rem; }
.guide-empty { font-size: 1.2rem; color: #7d859a; padding: 2rem .8rem; }
.gi { display: flex; align-items: center; padding: .75rem .8rem; border-radius: .6rem; cursor: pointer; border: .15rem solid transparent; }
.gi-time { width: 5rem; flex: none; font-size: 1.15rem; color: #9fb6ff; font-weight: 600; }
.gi-body { flex: 1; min-width: 0; }
.gi-title { font-size: 1.2rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gi-bar { height: .25rem; background: rgba(255, 255, 255, .12); margin-top: .4rem; border-radius: .2rem; overflow: hidden; }
.gi-badge { flex: none; margin-left: .8rem; font-size: .8rem; font-weight: 700; color: #fff; background: #e5484d; padding: .2rem .5rem; border-radius: .3rem; }
.gi.live .gi-title { font-weight: 700; }
.gi.sel { background: #fff; color: #0b0d12; }
.gi.sel .gi-time { color: #2f6bff; }
.guide-desc { padding: 1.4rem 2rem 2rem; border-top: .1rem solid #222839; background: #10131b; }
.gd-title { font-size: 1.4rem; font-weight: 700; }
.gd-meta { font-size: 1rem; color: #9fb6ff; margin: .3rem 0 .6rem; }
.gd-text { font-size: 1.05rem; color: #aab1c3; line-height: 1.45; max-height: 7.6rem; overflow: hidden; margin-bottom: 1rem; }
.muted { color: #7d859a; font-size: 1.1rem; }

/* ---------- impostazioni ---------- */
#settings { overflow-y: auto; }
.settings-wrap { width: 100%; max-width: 110rem; margin: 0 auto; padding: 3rem 4rem 4rem; }
.settings-wrap h1 { font-size: 2.6rem; margin: 0 0 1.5rem; }
.settings-wrap h2 { font-size: 1.4rem; color: #7d859a; font-weight: 600; margin: 2.2rem 0 1rem; text-transform: uppercase; letter-spacing: .1rem; }
.pl-row { display: flex; align-items: center; background: #131722; border-radius: .9rem; padding: 1rem 1.4rem; margin-bottom: .7rem;
  border: .15rem solid transparent; }
.pl-row.current { border-color: #2f6bff; }
.pl-info { flex: 1; min-width: 0; margin-right: 1rem; }
.pl-name { font-size: 1.35rem; font-weight: 600; }
.pl-url { font-size: 1rem; color: #6c7488; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pl-row .btn { margin-left: .8rem; }
.form-row { display: flex; align-items: center; flex-wrap: wrap; }
.form-row > * { margin: 0 .8rem .8rem 0; }
.form-row input { background: #161a25; border: .15rem solid #2a3145; border-radius: .8rem; padding: .9rem 1.2rem; font-size: 1.25rem; width: 22rem; }
.form-row input.wide { width: 48rem; }
.form-row input.focused { border-color: #fff; background: #1f2433; }
.note { margin-top: 2.5rem; font-size: 1.1rem; line-height: 1.6; color: #7d859a; max-width: 80rem; }

/* ---------- toast ---------- */
#toast { position: absolute; left: 50%; bottom: 4rem; transform: translateX(-50%); background: #fff; color: #0b0d12;
  padding: 1rem 2rem; border-radius: 3rem; font-size: 1.3rem; font-weight: 600; box-shadow: 0 .6rem 2rem rgba(0, 0, 0, .5);
  z-index: 50; white-space: nowrap; }

/* Telefoni/finestre strette (solo per test nel browser) */
@media (max-width: 900px) {
  html { font-size: 10px; }
  #sidebar { width: 17rem; padding-left: 1.2rem; }
  #main { padding: 1.5rem 1rem; }
  #search { width: 100%; }
  #playlist-name, #hint { display: none; }
  .osd-buttons { flex-wrap: wrap; }
  .osd-epg, .osd-help { display: none; }
  #guide, #picker { width: 100%; }
  #btn-multi { padding: .8rem; }
}

/* ===== Icone (www/js/icons.js): SVG a tratto, colore del testo ===== */
.ic { display: inline-block; width: 1.25em; height: 1.25em; vertical-align: -.25em; margin-right: .5em; flex-shrink: 0; }
.ic:last-child { margin-right: 0; }
.ict + .ic { margin-left: .9em; }
.btn .ic { width: 1.3em; height: 1.3em; }
#osd-pause .ic, #osd-fav .ic { width: 1.45em; height: 1.45em; vertical-align: -.3em; }
.osd-shift .ic-dot, .osd-shift .ic-live { color: #ff5a5a; }
#live-badge .ic-live, .tile-live .ic-live { color: #fff; }
.btn .ic-live { color: #ff5a5a; }
.btn.focused .ic-live, .btn.primary .ic-live { color: #e5484d; }
.btn.primary .ic-live { color: #fff; }
.ic-starf { color: #ffc93c; }
.btn.focused .ic-starf { color: #e0a800; }
.card .cstar .ic { width: 1.5rem; height: 1.5rem; margin: 0; }
.tile-audio .ic { margin: 0; width: 1.4rem; height: 1.4rem; vertical-align: middle; }
.tile-empty .ic { width: 3rem; height: 3rem; margin: 0 0 .6rem; }
.mb-title .ic { color: #aab1c3; }
.guide-day .ic { width: 1.1em; height: 1.1em; }

/* ===== Aggiungi dal telefono o dal PC ===== */
#pair { position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(5, 6, 10, .82); z-index: 50;
  display: flex; align-items: center; justify-content: center; }
#pair.hidden { display: none; }
.pair-box { width: 78rem; max-width: 94%; background: #131722; border: .15rem solid #2a3145; border-radius: 1.6rem; padding: 2.6rem 3rem; }
.pair-title { font-size: 2.1rem; font-weight: 800; margin-bottom: 2rem; }
.pair-title .ic { color: #ff6a3d; }
.pair-body { display: flex; align-items: flex-start; }
.pair-qr { width: 22rem; height: 22rem; flex-shrink: 0; background: #fff; border-radius: 1.2rem; margin-right: 3rem;
  display: flex; align-items: center; justify-content: center; overflow: hidden; }
.pair-qr img { width: 100%; height: 100%; image-rendering: pixelated; }
.pair-info { flex: 1; min-width: 0; }
.pair-step { font-size: 1.35rem; color: #c3c9d8; margin-bottom: 1rem; line-height: 1.45; }
.pair-step b { color: #fff; }
.pair-url { color: #fff; font-weight: 700; word-break: break-all; }
.pair-code { font-size: 3.4rem; font-weight: 800; letter-spacing: .35rem; color: #fff; background: #0b0d12; border-radius: 1rem;
  padding: 1rem 1.4rem; margin: .4rem 0 1.4rem; text-align: center; font-family: Consolas, "Roboto Mono", monospace; }
.pair-status { font-size: 1.25rem; color: #ffc93c; margin-top: 1rem; }
.pair-item { font-size: 1.25rem; color: #8ff0b4; margin-top: .6rem; }
.pair-foot { display: flex; align-items: center; justify-content: space-between; margin-top: 2rem; }
.pair-foot .muted { font-size: 1.05rem; margin-right: 2rem; }

/* ===== Multivisione su TV con un solo decoder: riquadri in attesa ===== */
.tile-standby { display: none; position: absolute; top: 0; left: 0; right: 0; bottom: 0; flex-direction: column;
  align-items: center; justify-content: center; background: #10131c; }
.tile.standby .tile-standby { display: flex; }
.tile.standby video { visibility: hidden; }
.tile.standby .tile-label { opacity: 1; z-index: 2; }
.tile-standby { z-index: 1; }
.tile-err { z-index: 2; }
.ts-logo { width: 9rem; height: 6rem; display: flex; align-items: center; justify-content: center; }
.ts-logo img { max-width: 100%; max-height: 100%; }
.ts-logo .initials { font-size: 2.6rem; font-weight: 800; color: #6c7488; }
.ts-hint { margin-top: 1rem; font-size: 1.1rem; color: #8f97ab; }
.tile.focused .ts-hint { color: #fff; }

/* Anteprima ferma (ultimo fotogramma) nei riquadri in attesa */
.ts-shot { display: none; position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: contain; }
.tile.has-shot .ts-shot { display: block; filter: brightness(.55); }
.tile.has-shot .ts-logo { display: none; }
.tile.has-shot .ts-hint { position: absolute; bottom: 1rem; left: 0; right: 0; text-align: center; color: #fff;
  text-shadow: 0 0 .6rem #000; }

/* ===== Benvenuto (nessuna playlist) ===== */
.welcome { width: 100%; padding: 6rem 4rem; text-align: center; }
.wl-title { font-size: 3rem; font-weight: 800; margin-bottom: 1rem; }
.wl-sub { font-size: 1.4rem; color: #aab1c3; max-width: 60rem; margin: 0 auto 3rem; line-height: 1.5; }
.wl-buttons .btn { margin: 0 .7rem; font-size: 1.4rem; padding: 1rem 1.8rem; }

/* =====================================================================================================
   TEMA "NEON" (stile BTV): blu notte, riflessi blu/viola, pannelli arrotondati con bordo luminoso.
   Sta in fondo al file e sovrascrive i colori precedenti: per tornare allo stile vecchio basta togliere questo blocco.
   ===================================================================================================== */
html, body { background: #050816; }
#app { background-color: #050816;
  background-image: radial-gradient(ellipse 60% 45% at 0% 100%, rgba(37, 99, 255, .32), rgba(37, 99, 255, 0) 70%),
    radial-gradient(ellipse 55% 40% at 100% 0%, rgba(140, 60, 255, .22), rgba(140, 60, 255, 0) 70%),
    radial-gradient(ellipse 50% 35% at 100% 100%, rgba(170, 60, 255, .22), rgba(170, 60, 255, 0) 70%); }
.screen { background: transparent; }
#player { background: #000; }

/* pulsanti e focus: bordo azzurro luminoso invece del bianco pieno */
.btn { background: rgba(14, 22, 52, .85); border: .12rem solid rgba(80, 130, 255, .35); border-radius: .9rem; color: #e6ecff; }
.btn.primary { background: #1e6bff; background-image: linear-gradient(135deg, #1f8bff, #6a3dff); border-color: transparent; color: #fff; }
.btn.danger { background: rgba(70, 18, 40, .85); border-color: rgba(255, 80, 120, .45); }
.btn.focused, .ibtn.focused, .ph-more.focused { background: #1f8bff; background-image: linear-gradient(135deg, #2fa8ff, #6a3dff);
  color: #fff; border-color: #8fd0ff; box-shadow: 0 0 0 .15rem rgba(120, 200, 255, .9), 0 0 1.8rem rgba(60, 150, 255, .75); transform: scale(1.06); }

/* barra laterale */
#sidebar { width: 21rem; background: rgba(6, 10, 28, .82); border-right: .1rem solid rgba(70, 110, 255, .22); padding: 2rem 1.2rem 1.6rem 1.6rem; }
.brand { margin-bottom: 1.6rem; justify-content: center; }
.brand-logo { width: 9.5rem; height: 9.5rem; border-radius: 1.8rem; box-shadow: 0 0 2.2rem rgba(60, 140, 255, .45); }
.group { font-size: 1.25rem; color: #c9d3f5; padding: .75rem 1rem; border-radius: .9rem; margin-bottom: .25rem; border: .12rem solid transparent; }
.group .gname .ic { color: #9fb6ff; }
.group .gcount { color: #6f7ca6; }
.group.active { color: #fff; background: #1d5cff; background-image: linear-gradient(90deg, #1f6bff, #3f8bff);
  box-shadow: 0 0 1.4rem rgba(40, 110, 255, .5); }
.group.active .gname .ic, .group.active .gcount { color: #fff; }
.group.focused { background: rgba(31, 107, 255, .25); color: #fff; border-color: #8fd0ff; transform: scale(1.03);
  box-shadow: 0 0 1.4rem rgba(60, 150, 255, .6); }
.group.focused .gcount { color: #fff; }
.side-info { display: flex; align-items: center; margin-top: 1rem; padding: 1rem 1.1rem; border-radius: 1rem;
  background: rgba(14, 22, 52, .85); border: .1rem solid rgba(80, 130, 255, .3); }
.side-info .ic { width: 2.6rem; height: 2.6rem; color: #9b7bff; margin-right: .9rem; }
.side-info b { display: block; font-size: 1.15rem; }
.side-info span { display: block; font-size: .95rem; color: #8c97bd; }

/* barra in alto */
#main { padding: 1.8rem 2.2rem 1rem 2rem; }
#topbar { margin-bottom: 1.2rem; }
.search-wrap { position: relative; width: 38rem; }
.search-wrap .ic { position: absolute; left: 1.3rem; top: 50%; margin-top: -.85rem; width: 1.7rem; height: 1.7rem; color: #9fb6ff; z-index: 1; }
#search { width: 100%; padding: .95rem 1.4rem .95rem 3.8rem; border-radius: 3rem; background: rgba(10, 16, 40, .85);
  border: .12rem solid rgba(80, 130, 255, .4); font-size: 1.25rem; color: #fff; }
#search.focused { border-color: #8fd0ff; box-shadow: 0 0 1.6rem rgba(60, 150, 255, .6); background: rgba(14, 24, 60, .95); }
.top-space { flex: 1; }
#playlist-name { flex: none; max-width: 30rem; text-align: left; margin-right: 1rem; padding: .7rem 1.3rem .7rem 3rem; border-radius: 3rem;
  background: rgba(10, 16, 40, .85); border: .12rem solid rgba(80, 130, 255, .4); color: #fff; font-size: 1.1rem; position: relative; }
#playlist-name:empty { display: none; }
#playlist-name::before { content: ""; position: absolute; left: 1.1rem; top: 50%; width: 1.2rem; height: 1.2rem; margin-top: -.6rem;
  border-radius: 50%; background: #22c55e; box-shadow: 0 0 .8rem rgba(34, 197, 94, .8); }
#clock { font-size: 1.5rem; font-weight: 700; color: #dfe7ff; margin-right: 1.2rem; letter-spacing: .05rem; }
.ibtn { width: 3.6rem; height: 3.6rem; border-radius: 50%; border: .12rem solid rgba(80, 130, 255, .4); background: rgba(10, 16, 40, .85);
  color: #dfe7ff; margin-left: .6rem; padding: 0; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.ibtn .ic { width: 1.8rem; height: 1.8rem; margin: 0; }
#btn-update { margin-left: 0; }
#btn-multi { margin-right: 0; }

/* pannelli della Home */
#home { flex: 1; display: flex; flex-direction: column; min-height: 0; }
.panel { position: relative; background: rgba(8, 14, 38, .78); border: .12rem solid rgba(80, 130, 255, .32); border-radius: 1.4rem;
  box-shadow: 0 0 2rem rgba(30, 80, 255, .12), inset 0 0 1.5rem rgba(60, 100, 255, .05); overflow: hidden; }
.h-top { flex: 55; display: flex; min-height: 0; margin-bottom: 1.2rem; }
.h-bottom { flex: 45; display: flex; min-height: 0; }
.ph { display: flex; align-items: center; padding: 1rem 1.3rem .6rem; font-size: 1.35rem; font-weight: 700; }
.ph .ic { width: 1.8rem; height: 1.8rem; margin-right: .7rem; color: #3fa2ff; }
#h-favs .ph .ic-starf { color: #ffc93c; }
.ph-t { flex: 1; }
.ph-date { font-size: 1.15rem; font-weight: 600; color: #c9d3f5; }
.ph-more { background: none; border: .12rem solid transparent; border-radius: .7rem; color: #c9d3f5; font-size: 1.05rem; padding: .3rem .7rem; cursor: pointer; }
.ph-more .ic { width: 1.3rem; height: 1.3rem; margin: 0 0 0 .4rem; color: inherit; }

/* anteprima */
#h-preview { flex: 63; margin-right: 1.2rem; background: #000; cursor: pointer; }
#h-preview video { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: contain; background: #000; }
#h-preview.focused { border-color: #8fd0ff; box-shadow: 0 0 0 .15rem rgba(120, 200, 255, .9), 0 0 2.4rem rgba(60, 150, 255, .7); }
.pv-empty { display: none; position: absolute; top: 45%; left: 0; right: 0; text-align: center; font-size: 1.4rem; color: #8c97bd; }
#h-preview.empty .pv-empty { display: block; }
#h-preview.empty .pv-info, #h-preview.empty .pv-live, #h-preview.empty .pv-bar { display: none; }
.pv-spin { display: none; position: absolute; top: 50%; left: 50%; margin: -3rem 0 0 -3rem; }
#h-preview.loading .pv-spin { display: block; }
.pv-live { position: absolute; top: 1.2rem; right: 1.4rem; font-size: 1rem; font-weight: 800; letter-spacing: .1rem; color: #fff;
  background: rgba(0, 0, 0, .55); padding: .3rem .8rem; border-radius: .5rem; }
.pv-live span { display: inline-block; width: .7rem; height: .7rem; border-radius: 50%; background: #ff3b3b; margin-right: .5rem; box-shadow: 0 0 .6rem #ff3b3b; }
.pv-info { position: absolute; left: 1.4rem; right: 1.4rem; bottom: 4.6rem; display: flex; align-items: center; text-shadow: 0 0 .6rem #000; }
.pv-logo { width: 6rem; height: 4rem; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, .45);
  border-radius: .7rem; margin-right: 1rem; flex: none; }
.pv-logo img { max-width: 90%; max-height: 90%; }
.pv-text { min-width: 0; }
.pv-name { font-size: 1.5rem; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pv-now { font-size: 1.1rem; color: #dfe7ff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pv-bar { position: absolute; left: 0; right: 0; bottom: 0; display: flex; align-items: center; padding: .9rem 1.4rem;
  background: linear-gradient(0deg, rgba(0, 0, 0, .85), rgba(0, 0, 0, 0)); }
.pv-bar .ic { width: 1.6rem; height: 1.6rem; margin-right: 1.1rem; color: #fff; }
.pv-prog { flex: 1; height: .35rem; border-radius: .2rem; background: rgba(255, 255, 255, .2); margin-right: 1rem; overflow: hidden; }
.pv-prog i { display: block; height: 100%; width: 0; background: #2fa8ff; box-shadow: 0 0 .6rem #2fa8ff; }
.pv-red { font-size: 1rem; font-weight: 800; color: #fff; margin-right: 1.2rem; }
.pv-red::before { content: ""; display: inline-block; width: .7rem; height: .7rem; border-radius: 50%; background: #ff3b3b; margin-right: .4rem; }
.pv-hint { font-size: 1rem; color: #c9d3f5; margin-right: 1rem; }

/* guida della Home */
#h-guide { flex: 37; display: flex; flex-direction: column; }
#hg-list { flex: 1; overflow-y: auto; padding: 0 .8rem .8rem; }
#hg-list::-webkit-scrollbar { width: 0; }
.hg-row { display: flex; align-items: center; padding: .55rem .6rem; border-radius: .8rem; border: .12rem solid transparent;
  border-bottom-color: rgba(80, 130, 255, .12); cursor: pointer; }
.hg-ch { width: 8.5rem; flex: none; display: flex; align-items: center; }
.hg-logo { width: 3.6rem; height: 2.4rem; display: flex; align-items: center; justify-content: center; margin-right: .6rem; }
.hg-logo img { max-width: 100%; max-height: 100%; }
.hg-logo .initials { font-size: 1.1rem; }
.hg-num { font-size: 1.05rem; font-weight: 700; color: #9fb6ff; }
.hg-time { width: 9.5rem; flex: none; font-size: 1.05rem; color: #c9d3f5; }
.hg-title { flex: 1; min-width: 0; font-size: 1.15rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hg-row.playing .hg-title { color: #7fc4ff; }
.hg-row.focused { background: #1d5cff; background-image: linear-gradient(90deg, #1f6bff, #3f8bff); border-color: #8fd0ff;
  box-shadow: 0 0 1.4rem rgba(60, 150, 255, .6); }
.hg-row.focused .hg-num, .hg-row.focused .hg-time, .hg-row.focused .hg-title { color: #fff; }

/* preferiti, categorie, continua a guardare */
#h-favs { flex: 34; margin-right: 1.2rem; }
#h-cats { flex: 34; margin-right: 1.2rem; }
#h-cont { flex: 32; }
.tiles { display: flex; flex-wrap: wrap; padding: .2rem 1rem 1rem; }
.tiles-empty { font-size: 1.1rem; color: #8c97bd; padding: 1rem .4rem; line-height: 1.5; }
.ftile, .ctile { width: 23%; margin: 0 2% 2% 0; height: 7.6rem; border-radius: 1rem; background: rgba(18, 28, 66, .85);
  border: .12rem solid rgba(80, 130, 255, .25); display: flex; flex-direction: column; align-items: center; justify-content: center;
  cursor: pointer; overflow: hidden; }
.ftile:nth-child(4n), .ctile:nth-child(4n) { margin-right: 0; }
.ft-logo { width: 80%; height: 4.4rem; display: flex; align-items: center; justify-content: center; }
.ft-logo img { max-width: 100%; max-height: 100%; }
.ft-name, .ct-name { font-size: .95rem; color: #dfe7ff; margin-top: .3rem; max-width: 92%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ctile .ic { width: 2.8rem; height: 2.8rem; margin: 0; color: #3fa2ff; }
.ctile .ic-trophy { color: #ffc23c; }
.ctile .ic-film { color: #b06bff; }
.ctile .ic-smile { color: #ffd23c; }
.ctile .ic-music { color: #4fb0ff; }
.ctile .ic-news, .ctile .ic-doc { color: #58c8ff; }
.ftile.focused, .ctile.focused { border-color: #8fd0ff; background: rgba(31, 107, 255, .35); transform: scale(1.07);
  box-shadow: 0 0 1.6rem rgba(60, 150, 255, .7); }
.kcard { position: relative; margin: .2rem 1.2rem 1rem; height: 15.5rem; border-radius: 1.1rem; overflow: hidden;
  background: radial-gradient(ellipse at 50% 30%, rgba(60, 120, 255, .45), rgba(10, 16, 40, .9) 70%); border: .1rem solid rgba(80, 130, 255, .3); }
.k-logo { position: absolute; top: 1.2rem; left: 0; right: 0; height: 6rem; display: flex; align-items: center; justify-content: center; }
.k-logo img { max-height: 100%; max-width: 60%; }
.k-name { position: absolute; left: 1.2rem; bottom: 4.3rem; font-size: 1.35rem; font-weight: 800; }
.k-now { position: absolute; left: 1.2rem; right: 1.2rem; bottom: 2.9rem; font-size: 1rem; color: #c9d3f5; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.k-go { position: absolute; right: 1rem; bottom: .7rem; font-size: 1.05rem; padding: .55rem 1.1rem; }

/* griglia dei canali */
#status { color: #8c97bd; }
#hint { color: #5b6690; }
.card { background: rgba(10, 16, 40, .8); border: .12rem solid rgba(80, 130, 255, .25); border-radius: 1.1rem; }
.card .clogo { background: rgba(18, 28, 66, .7); }
.card .cbar i, .osd-bar i, .gi-bar i { background: #2fa8ff; }
.card.focused { border-color: #8fd0ff; background: rgba(20, 40, 100, .9); box-shadow: 0 0 0 .12rem rgba(120, 200, 255, .9), 0 0 2rem rgba(60, 150, 255, .7); }
.welcome .wl-title { background: linear-gradient(90deg, #4fb0ff, #b06bff); -webkit-background-clip: text; color: transparent; }

/* impostazioni, pannelli laterali, multivisione, lettore */
.pl-row { background: rgba(10, 16, 40, .8); border: .12rem solid rgba(80, 130, 255, .25); }
.pl-row.current { border-color: #3f8bff; box-shadow: 0 0 1.2rem rgba(40, 110, 255, .35); }
.form-row input { background: rgba(10, 16, 40, .85); border-color: rgba(80, 130, 255, .4); }
.form-row input.focused { border-color: #8fd0ff; box-shadow: 0 0 1.4rem rgba(60, 150, 255, .55); background: rgba(14, 24, 60, .95); }
#picker, #guide { background: rgba(5, 9, 26, .97); border-left: .12rem solid rgba(80, 130, 255, .35); box-shadow: -1rem 0 3rem rgba(20, 60, 255, .2); }
.pair-box { background: rgba(8, 14, 38, .96); border-color: rgba(80, 130, 255, .45); box-shadow: 0 0 3rem rgba(30, 90, 255, .35); }
.tile { border-color: rgba(80, 130, 255, .25); border-radius: .8rem; }
.tile.focused { border-color: #8fd0ff; box-shadow: 0 0 1.6rem rgba(60, 150, 255, .7); }
#osd { background: linear-gradient(0deg, rgba(3, 6, 20, .96) 0%, rgba(3, 6, 20, .8) 55%, rgba(3, 6, 20, 0) 100%); }
.osd-num { color: #7fc4ff; }
#toast { background: #1f6bff; background-image: linear-gradient(135deg, #1f8bff, #6a3dff); color: #fff; box-shadow: 0 0 2rem rgba(60, 120, 255, .6); }

/* ===== Home v2: guida a tutta altezza, preferiti + canale precedente / più visti ===== */
#home { flex-direction: row; }
.h-left { flex: 63; display: flex; flex-direction: column; min-width: 0; margin-right: 1.2rem; }
#h-preview { flex: 56; margin: 0 0 1.2rem; }
.h-left .h-bottom { flex: 44; display: flex; min-height: 0; }
#h-guide { flex: 37; }
#h-favs { flex: 55; margin-right: 1.2rem; }
#h-quick { flex: 45; }
.ph-sub { padding-top: .4rem; }
.hg-row { padding: .45rem .6rem; }
.hg-ch { width: 7.6rem; }
.hg-prog { flex: 1; min-width: 0; }
.hg-l1 { display: flex; align-items: baseline; min-width: 0; }
.hg-time { width: auto; flex: none; margin-right: .7rem; font-size: 1rem; font-weight: 700; color: #7fc4ff; }
.hg-title { font-size: 1.15rem; }
.hg-next { font-size: .95rem; color: #8c97bd; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: .1rem; }
.hg-row.focused .hg-next { color: #e6ecff; }
.qtile { display: flex; align-items: center; border-radius: 1rem; background: rgba(18, 28, 66, .85); border: .12rem solid rgba(80, 130, 255, .25);
  cursor: pointer; overflow: hidden; padding: .5rem .8rem; }
.qtile.wide { margin: 0 1rem .4rem; height: 5.6rem; }
