.glogo { width: 3.2rem; height: 2rem; flex: none; margin-right: .7rem; display: flex; align-items: center; justify-content: center;
  border-radius: .45rem; background: rgba(255, 255, 255, .06); overflow: hidden; }
.glogo img { max-width: 92%; max-height: 88%; object-fit: contain; }
.glogo .ic { width: 1.4rem; height: 1.4rem; margin: 0; color: #9fb6ff; }
