.group .gname .ict { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* preferiti: 3 per riga, logo, nome e programma leggibili */
#h-favs .ftile { width: 32%; margin: 0 2% 2% 0; height: 9.6rem; padding: .4rem .5rem; }
