/* logo di marchio nelle cartelle: riquadro scuro come i loghi dei canali */
.glogo img { max-width: 100%; max-height: 100%; }
.group .glogo:has(img) { width: 3.2rem; background: rgba(255, 255, 255, .06); }

/* barra laterale: voci principali in grassetto con icona, categorie solo col nome */
.group.special .gname { font-weight: 800; color: #fff; }
.group.special { margin-bottom: .35rem; }
.group[data-group="__all"] { margin-bottom: 1rem; }
.group:not(.special) .gname { padding-left: .4rem; }

/* preferiti: il programma va a capo su due righe invece di tagliarsi */
#h-favs .tile-now { white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
  line-height: 1.2; max-height: 2.4em; text-align: center; font-size: .95rem; }
#h-favs .ft-name { white-space: normal; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; text-align: center; }
#h-favs .ftile { height: 10.4rem; justify-content: flex-start; padding-top: .6rem; }
#h-favs .ft-logo { height: 4.2rem; }
#h-favs .ftile { height: 8.6rem; padding-top: .45rem; margin-bottom: 1.5%; }
#h-favs .ft-logo { height: 3.2rem; }
#h-favs .ft-name { font-size: 1.05rem; margin-top: .25rem; }
#h-favs .tile-now { font-size: .9rem; }
#h-favs .tiles { padding-top: 0; }

/* niente etichetta playlist/guida in alto */
#playlist-name { display: none !important; }
/* riordino dei preferiti */
#grid-tools { display: flex; align-items: center; margin: 0 0 .6rem; }
#grid-tools.hidden { display: none; }
#reorder-hint { margin-left: 1.2rem; font-size: 1.1rem; color: #7fc4ff; }
#grid.reordering .card { border-style: dashed; }
.card.moving { border: .2rem solid #ffc93c !important; box-shadow: 0 0 2rem rgba(255, 201, 60, .7) !important; transform: scale(1.1); }

/* pulsante Multivisione in alto: icona + scritta */
.top-btn { margin-left: .6rem; padding: .7rem 1.3rem; border-radius: 3rem; font-size: 1.1rem; }

/* ===== TV e Fire TV (body.low-power): stesso aspetto, senza effetti costosi per i processori delle TV =====
   niente animazioni, niente ingrandimenti, niente ombre sfocate e sfondo a sfumature: il focus resta ben visibile
   con un bordo luminoso netto (un'ombra senza sfocatura costa pochissimo). */
.low-power *, .low-power *::before, .low-power *::after { transition: none !important; }
.low-power #app { background-image: none; background-color: #060a1c; }
.low-power .panel, .low-power .card, .low-power .btn, .low-power .ibtn, .low-power .group, .low-power .hg-row,
.low-power .ftile, .low-power .qtile, .low-power .ctile, .low-power .tile, .low-power .brand-logo, .low-power #toast,
.low-power #search, .low-power .pv-prog i, .low-power .pv-live span, .low-power #picker, .low-power #guide,
.low-power .pair-box, .low-power .pl-row, .low-power .form-row input { box-shadow: none !important; }
.low-power .focused { transform: none !important; box-shadow: 0 0 0 .22rem #8fd0ff !important; }
.low-power .pv-info, .low-power .ts-hint { text-shadow: none; }
.low-power .pv-bar { background: rgba(0, 0, 0, .55); }

/* riquadro "È disponibile un aggiornamento" in basso a sinistra (al posto di "BTV Player") */
.side-update { display: flex; align-items: center; width: 100%; margin-top: 1rem; padding: 1rem 1.1rem; border-radius: 1rem; text-align: left;
  cursor: pointer; color: #fff; border: .15rem solid #ffc93c; background: #1f6bff; background-image: linear-gradient(135deg, #1f8bff, #6a3dff); }
.side-update.hidden { display: none; }
.side-update .ic { width: 2.6rem; height: 2.6rem; margin-right: .9rem; color: #ffc93c; flex: none; }
.side-update b { display: block; font-size: 1.1rem; line-height: 1.25; }
.side-update span { display: block; }
.side-update span { font-size: .95rem; color: #e6ecff; margin-top: .2rem; }
.side-update.focused { border-color: #fff; box-shadow: 0 0 0 .22rem #fff, 0 0 2rem rgba(255, 201, 60, .7); }
.low-power .side-update.focused { box-shadow: 0 0 0 .22rem #fff !important; }

